-- Conflict C6: rejections and every other lifecycle fact go to trade.trade_activity, and every
-- status change to trade.trade_state_changes. Both only grow. Generated by appendOnly() in
-- src/db/helpers/appendOnly.ts — UPDATE and DELETE raise KT001 for everyone including the owner,
-- and komtru_app holds INSERT and SELECT only. No hand-written grants: grantRuntimeAccess() finds
-- the trigger on every later migrate run and keeps the privileges narrow.
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "trade"."trade_state_changes" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "trade"."trade_state_changes" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "trade"."trade_state_changes" TO komtru_app;
--> statement-breakpoint
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "trade"."trade_activity" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "trade"."trade_activity" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "trade"."trade_activity" TO komtru_app;